"use client";
import * as React from "react";
import { SculptureStage,type MaterialSculptureCommonProps } from "@/components/ui/glass-sculpture";
import { sculptureNumber } from "@/lib/cojeev/sculpture-raster";
export type FlowSculptureProps=MaterialSculptureCommonProps&{distortion?:number;chromatic?:number;spread?:number;settle?:number;swirl?:number;pulse?:number};
/** Pointer impulses advect and dissipate in a bounded field above a real rendered object. */
export function FlowSculpture({distortion=1,chromatic=.5,spread=.14,settle=1,swirl=.35,pulse=0,...props}:FlowSculptureProps){
 return <SculptureStage {...props} effect={{kind:"flow",distortion:sculptureNumber(distortion,1,0,2),chromatic:sculptureNumber(chromatic,.5,0,1),spread:sculptureNumber(spread,.14,.035,.3),settle:sculptureNumber(settle,1,.25,3),swirl:sculptureNumber(swirl,.35,0,1),pulse:sculptureNumber(pulse,0,0,Number.MAX_SAFE_INTEGER)}}/>;
}

"use client";
import * as React from "react";
import { assignMotionRef } from "@/lib/cojeev-motion/refs";
import { cn } from "@/lib/utils";
import { createGlyphMesh } from "@/lib/cojeev/glyph-mesh";
import { sculptureGeometry } from "@/lib/cojeev/sculpture-geometry";
import { rasterizeSculpture, sculptureGrid, sculpturePrint, sculpturePrintPath, sculptureNumber } from "@/lib/cojeev/sculpture-raster";
import { useMotionVisibility } from "@/lib/cojeev-motion/use-motion-visibility";
import type { SculptureCommonProps } from "@/components/ui/glyph-sculpture";
import { createMaterialRenderer, type MaterialEffect, type MaterialConfiguration, type MaterialRenderer } from "@/lib/cojeev/sculpture-renderer";
export type SculptureRendererState="pending"|"webgl"|"fallback"|"error";
export type MaterialSculptureCommonProps=SculptureCommonProps&{ref?:React.Ref<HTMLDivElement>;onRendererChange?:(state:SculptureRendererState)=>void};
type StageControl = {configure:(configuration:MaterialConfiguration)=>void;repaint:()=>void};

/** Shared native scene boundary; materials never take ownership of page input or scroll. */
export function SculptureStage({effect,form="bloom",tone="sky",geometry,speed=1,turn=0,pitch=0,zoom=1,pointerTracking=true,paused=false,onGeometryError,onRendererChange,className,ref,...props}:MaterialSculptureCommonProps&{effect:MaterialEffect}){
 const host=React.useRef<HTMLDivElement>(null),canvas=React.useRef<HTMLCanvasElement>(null),control=React.useRef<StageControl|null>(null),{enabled,inView}=useMotionVisibility(host);
 const attach=React.useCallback((node:HTMLDivElement|null)=>{host.current=node;const release=assignMotionRef(ref,node);return()=>{host.current=null;release();};},[ref]);
 const safeForm=form==="seed"||form==="pebble"?form:"bloom",safeTone=tone==="rose"||tone==="ink"||tone==="moss"?tone:"sky",pace=sculptureNumber(speed,1,0,3),degrees=sculptureNumber(turn,0,-180,180),tilt=sculptureNumber(pitch,0,-80,80),scale=sculptureNumber(zoom,1,.6,1.15);
 const meshResult=React.useMemo(()=>{try{return {mesh:sculptureGeometry(geometry??createGlyphMesh(safeForm)),error:null};}catch(error){return {mesh:null,error:error instanceof Error?error:new Error("The geometry could not be read.")};}},[geometry,safeForm]);
 const mesh=meshResult.mesh,kind=effect.kind;
 React.useEffect(()=>{if(meshResult.error)onGeometryError?.(meshResult.error);},[meshResult.error,onGeometryError]);
 const configuration=React.useMemo<MaterialConfiguration>(()=>({effect,visible:inView,quiet:!enabled,run:enabled&&!paused&&pace>0,respond:enabled&&!paused&&pace>0&&pointerTracking,turn:degrees,pitch:tilt,zoom:scale,speed:pace}),[effect,inView,enabled,paused,pace,pointerTracking,degrees,tilt,scale]);
 const latest=React.useRef(configuration);
 const [rendered,setRendered]=React.useState<{mesh:typeof mesh;kind:typeof kind;status:"pending"|"webgl"|"fallback"}>({mesh:null,kind,status:"pending"});
 const renderer=rendered.mesh===mesh&&rendered.kind===kind?rendered.status:"pending";
 React.useEffect(()=>{onRendererChange?.(meshResult.error?"error":renderer);},[renderer,meshResult.error,onRendererChange]);
 const still=React.useMemo(()=>{if(!mesh)return null;const grid=sculptureGrid(384,288,4),frame=rasterizeSculpture(mesh,grid,.35+degrees*Math.PI/180,-.16+tilt*Math.PI/180,scale);return {grid,path:sculpturePrintPath(sculpturePrint(frame,{kind:"dither",pattern:"ordered",density:1}),grid.columns)};},[mesh,degrees,tilt,scale]);
 React.useEffect(()=>{latest.current=configuration;control.current?.configure(configuration);},[configuration]);
 React.useEffect(()=>{control.current?.repaint();},[safeTone]);
 React.useEffect(()=>{
  const element=host.current,surface=canvas.current;if(!element||!surface||!mesh)return;
  let disposed=false,engine:MaterialRenderer|undefined,frame=0,last=0,elapsed=0,options=latest.current,job:AbortController|undefined,painted=false,lost=false;
  let previousPointer:{x:number;y:number}|undefined;
  const hover=window.matchMedia("(any-hover: hover) and (any-pointer: fine)");
  const colors=()=>{const css=getComputedStyle(element);return {paper:css.backgroundColor,ink:css.getPropertyValue("--v-text").trim()||"#20252a",accent:css.getPropertyValue("--material-accent").trim()||"#a6bde8",other:css.getPropertyValue("--v-yellow").trim()||"#edcf70"};};
  function cancel(){if(frame)cancelAnimationFrame(frame);frame=0;last=0;}
  function request(){if(!disposed&&!lost&&engine&&options.visible&&!document.hidden&&!frame)frame=requestAnimationFrame(draw);}
  function fallback(){if(disposed)return;cancel();job?.abort();engine?.dispose(false);engine=undefined;painted=false;setRendered({mesh,kind,status:"fallback"});}
  function draw(time:number){frame=0;if(disposed||lost||!engine||!options.visible||document.hidden)return;if(options.run&&last&&time-last<32){request();return;}const seconds=last?Math.min((time-last)/1000,1/30):1/30;last=time;if(options.run)elapsed+=seconds*options.speed;
   try{const again=engine.draw(seconds,elapsed);if(!painted){painted=true;setRendered({mesh,kind,status:"webgl"});}if(again)request();}catch{fallback();}
  }
  function resize(){if(!engine)return;const bounds=element!.getBoundingClientRect();engine.resize(bounds.width,bounds.height,window.devicePixelRatio||1);request();}
  function repaint(){engine?.colors(colors());request();}
  async function initialize(){if(disposed||lost||engine||job||!options.visible||document.hidden)return;job=new AbortController();const ownJob=job;
   try{const next=await createMaterialRenderer(surface!,mesh!,options,colors(),ownJob.signal);if(disposed||ownJob.signal.aborted){next.dispose(!surface!.isConnected);return;}engine=next;engine.configure(options);resize();request();}catch{if(!disposed&&!ownJob.signal.aborted)fallback();}
   finally{if(job===ownJob)job=undefined;}
  }
  const instance:StageControl={configure(next){options=next;engine?.configure(next);if(!next.respond){engine?.leave();previousPointer=undefined;}cancel();if(!engine)void initialize();else request();},repaint};control.current=instance;
  function pointer(event:PointerEvent){if(!engine||!options.respond||!options.visible||!hover.matches||event.pointerType==="touch"||document.hidden)return;const rect=element!.getBoundingClientRect(),x=(event.clientX-rect.left)/rect.width,y=1-(event.clientY-rect.top)/rect.height;
   if(x<0||x>1||y<0||y>1){engine.leave();previousPointer=undefined;return;}const dx=previousPointer?x-previousPointer.x:.025,dy=previousPointer?y-previousPointer.y:.01;previousPointer={x,y};engine.pointer(x,y,dx,dy);request();
  }
  const visibility=()=>{cancel();engine?.leave();previousPointer=undefined;if(!document.hidden){if(!engine)void initialize();request();}},leave=()=>{engine?.leave();previousPointer=undefined;},onLost=(event:Event)=>{event.preventDefault();lost=true;fallback();},onRestored=()=>{lost=false;painted=false;void initialize();};
  const sizeObserver=new ResizeObserver(resize);sizeObserver.observe(element);const appearance=new MutationObserver(repaint);for(let ancestor:Element|null=element;ancestor;ancestor=ancestor.parentElement)appearance.observe(ancestor,{attributes:true,attributeFilter:["class","style","data-mode"]});
  window.addEventListener("pointermove",pointer,{passive:true});window.addEventListener("blur",leave);window.addEventListener("resize",resize);window.addEventListener("cojeev:appearancechange",repaint);document.addEventListener("visibilitychange",visibility);surface.addEventListener("webglcontextlost",onLost);surface.addEventListener("webglcontextrestored",onRestored);void initialize();
  return()=>{disposed=true;job?.abort();cancel();if(control.current===instance)control.current=null;sizeObserver.disconnect();appearance.disconnect();window.removeEventListener("pointermove",pointer);window.removeEventListener("blur",leave);window.removeEventListener("resize",resize);window.removeEventListener("cojeev:appearancechange",repaint);document.removeEventListener("visibilitychange",visibility);surface.removeEventListener("webglcontextlost",onLost);surface.removeEventListener("webglcontextrestored",onRestored);engine?.dispose(!surface.isConnected);surface.width=1;surface.height=1;};
 },[mesh,kind]);
 return <div {...props} ref={attach} className={cn("v-material-sculpture",className)} data-slot={`${kind}-sculpture`} data-tone={safeTone} data-renderer={meshResult.error?"error":renderer} data-moving={configuration.run&&inView&&renderer==="webgl"?"true":"false"}>
  {meshResult.error?<span data-slot="material-status" role="status">{meshResult.error.message}</span>:still&&<svg data-slot="material-still" viewBox={`0 0 ${still.grid.columns} ${still.grid.rows}`} aria-hidden="true"><path d={still.path} fill="currentColor"/></svg>}
  <canvas ref={canvas} data-slot="material-canvas" aria-hidden="true" inert/>
  {!meshResult.error&&renderer!=="webgl"&&<span data-slot="material-status" role={renderer==="fallback"?"status":undefined}>{renderer==="fallback"?"3D material is unavailable. ":""}Static shape preview</span>}
 </div>;
}

import type * as React from 'react'
/** React 19 callback refs may return their own teardown; object refs are mutable commit targets. */
export function assignMotionRef<T>(ref:React.Ref<T>|undefined,value:T|null):()=>void{
 if(typeof ref==='function'){
  const cleanup=ref(value)
  return ()=>{if(typeof cleanup==='function')cleanup();else ref(null)}
 }
 if(ref)ref.current=value
 return ()=>{if(ref)ref.current=null}
}

import { rasterizeSculpture } from "@/lib/cojeev/sculpture-raster";
/** Original organic geometry and a small, dependency-free character-cell rasterizer. */
export type GlyphForm = "seed" | "bloom" | "pebble";
export type GlyphTone = "ink" | "rose" | "moss" | "sky";
export const GLYPH_RAMP = " .,:;=+*#%@";
type Vector = [number, number, number];
export type GlyphMesh = { positions: Float32Array; normals: Float32Array; triangles: Uint16Array };
export type GlyphGrid = { columns: number; rows: number; cellWidth: number; cellHeight: number; width: number; height: number };
const bounded = (value: number | undefined, fallback: number, min: number, max: number) => Number.isFinite(value) ? Math.max(min, Math.min(max, value!)) : fallback;

export function normalizeGlyphOptions({ speed, cellSize, turn }: { speed?: number; cellSize?: number; turn?: number } = {}) {
  return { speed: bounded(speed, 1, 0, 3), cellSize: bounded(cellSize, 10, 7, 20), turn: bounded(turn, 0, -180, 180) };
}

export function glyphGrid(width: number, height: number, cellSize: number): GlyphGrid {
  width = bounded(width, 1, 1, 20000); height = bounded(height, 1, 1, 20000);
  const size = Math.max(bounded(cellSize, 10, 7, 20), width / (140 * .62), height / 90);
  const columns = Math.max(1, Math.min(140, Math.floor(width / (size * .62))));
  const rows = Math.max(1, Math.min(90, Math.floor(height / size)));
  return { columns, rows, cellWidth: width / columns, cellHeight: height / rows, width, height };
}

function surface(form: GlyphForm, longitude: number, latitude: number): Vector {
  const ring = Math.sin(latitude), height = Math.cos(latitude);
  const x = Math.cos(longitude), z = Math.sin(longitude);
  if (form === "seed") return [.69 * ring * x * (1 + .2 * height), 1.08 * height, .5 * ring * z * (1 - .18 * height)];
  if (form === "bloom") {
    // A soft five-lobed cushion, with a shallow dimple at the center of each face.
    const radius = .83 + .19 * Math.cos(5 * longitude);
    return [radius * ring * x, radius * ring * z, .44 * height * (1 - .28 * Math.exp(-ring * ring * 12))];
  }
  const radius = 1 + .09 * Math.cos(3 * longitude + .3) * ring;
  return [.94 * ring * x * radius, .79 * height + .05 * ring * Math.sin(2 * longitude), .66 * ring * z * radius];
}

function unit(x: number, y: number, z: number): Vector {
  const length = Math.hypot(x, y, z) || 1;
  return [x / length, y / length, z / length];
}

export function createGlyphMesh(form: GlyphForm): GlyphMesh {
  const around = 64, vertical = 32;
  const positions = new Float32Array((around + 1) * (vertical + 1) * 3);
  const normals = new Float32Array(positions.length);
  const triangles: number[] = [];
  for (let row = 0; row <= vertical; row++) for (let column = 0; column <= around; column++) {
    const longitude = column / around * Math.PI * 2, latitude = row / vertical * Math.PI;
    const index = (row * (around + 1) + column) * 3;
    const point = surface(form, longitude, latitude);
    positions.set(point, index);
    const u0 = surface(form, longitude - .001, latitude), u1 = surface(form, longitude + .001, latitude);
    const v0 = surface(form, longitude, latitude - .001), v1 = surface(form, longitude, latitude + .001);
    const u = u1.map((value, i) => value - u0[i]), v = v1.map((value, i) => value - v0[i]);
    let normal = unit(u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0]);
    if (row === 0 || row === vertical) normal = unit(...point);
    if (normal.reduce((sum, value, i) => sum + value * point[i], 0) < 0) normal = normal.map(value => -value) as Vector;
    normals.set(normal, index);
    if (row < vertical && column < around) {
      const a = row * (around + 1) + column, b = a + around + 1;
      triangles.push(a, b, a + 1, a + 1, b, b + 1);
    }
  }
  return { positions, normals, triangles: new Uint16Array(triangles) };
}

/** Compatibility density-grid API backed by the shared depth-tested surface. */
export function rasterizeGlyphs(mesh: GlyphMesh, grid: GlyphGrid, yaw = .35, pitch = -.2): Uint8Array {
  const frame = rasterizeSculpture(mesh, grid, yaw, pitch), cells = new Uint8Array(frame.coverage.length);
  for (let i = 0; i < cells.length; i++) if (frame.coverage[i]) cells[i] = Math.max(1, Math.min(GLYPH_RAMP.length - 1, Math.round(frame.light[i] * (GLYPH_RAMP.length - 2)) + 1));
  return cells;
}

export function glyphText(cells: Uint8Array, columns: number): string {
  const lines: string[] = [];
  for (let i = 0; i < cells.length; i += columns) lines.push(Array.from(cells.subarray(i, i + columns), value => GLYPH_RAMP[value]).join(""));
  return lines.join("\n");
}

import type { SculptureGeometry } from "@/lib/cojeev/sculpture-geometry";

export type SculptureGrid = { columns: number; rows: number; cellWidth: number; cellHeight: number; width: number; height: number };
export type SculptureFrame = { grid: SculptureGrid; coverage: Uint8Array; light: Float32Array; depth: Float32Array; sampling: number };
export const sculptureNumber = (value: number | undefined, fallback: number, min: number, max: number) => Number.isFinite(value) ? Math.max(min, Math.min(max, value!)) : fallback;
export function sculptureGrid(width: number, height: number, step = 2): SculptureGrid {
  width = sculptureNumber(width, 1, 1, 20000); height = sculptureNumber(height, 1, 1, 20000);
  step = Math.max(sculptureNumber(step, 2, 1.5, 12), width / 280, height / 220);
  const columns = Math.max(1, Math.floor(width / step)), rows = Math.max(1, Math.floor(height / step));
  return { columns, rows, cellWidth: width / columns, cellHeight: height / rows, width, height };
}

/** Original orthographic depth pass. The same surface supplies glyphs, print dots and engraved lines. */
export function rasterizeSculpture(mesh: SculptureGeometry, grid: SculptureGrid, yaw = .35, pitch = -.2, zoom = 1): SculptureFrame {
  const { columns, rows, cellWidth, cellHeight, width, height } = grid;
  const coverage = new Uint8Array(columns * rows), depth = new Float32Array(coverage.length).fill(-Infinity), light = new Float32Array(coverage.length);
  const projected = new Float32Array(mesh.positions.length / 3 * 4), cy = Math.cos(yaw), sy = Math.sin(yaw), cx = Math.cos(pitch), sx = Math.sin(pitch);
  const angle = -.14, cz = Math.cos(angle), sz = Math.sin(angle), scale = Math.min(width, height) * .39 * sculptureNumber(zoom, 1, .6, 1.15);
  function rotate(x: number, y: number, z: number) { const a = cy * x + sy * z, b = -sy * x + cy * z, c = cx * y - sx * b; return [cz * a - sz * c, sz * a + cz * c, sx * y + cx * b]; }
  for (let i = 0, out = 0; i < mesh.positions.length; i += 3, out += 4) {
    const p = rotate(mesh.positions[i], mesh.positions[i + 1], mesh.positions[i + 2]), n = rotate(mesh.normals[i], mesh.normals[i + 1], mesh.normals[i + 2]);
    projected[out] = columns / 2 + p[0] * scale / cellWidth; projected[out + 1] = rows / 2 - p[1] * scale / cellHeight; projected[out + 2] = p[2];
    projected[out + 3] = Math.min(1, .12 + .8 * Math.max(0, n[0] * -.42 + n[1] * .58 + n[2] * .69) + .12 * Math.abs(n[2]));
  }
  // Vertex/triangle limits alone cannot bound overlapping triangle work. Estimate
  // clipped coverage first, then lower sampling before any expensive raster pass.
  let work = 0;
  for (let i = 0; i < mesh.triangles.length; i += 3) {
    const a = mesh.triangles[i] * 4, b = mesh.triangles[i + 1] * 4, c = mesh.triangles[i + 2] * 4;
    const left = Math.max(0, Math.floor(Math.min(projected[a], projected[b], projected[c]))), right = Math.min(columns - 1, Math.ceil(Math.max(projected[a], projected[b], projected[c])));
    const top = Math.max(0, Math.floor(Math.min(projected[a + 1], projected[b + 1], projected[c + 1]))), bottom = Math.min(rows - 1, Math.ceil(Math.max(projected[a + 1], projected[b + 1], projected[c + 1])));
    work += Math.max(0, right - left + 1) * Math.max(0, bottom - top + 1);
  }
  if (work > 350000 && (columns > 1 || rows > 1)) {
    const factor = Math.sqrt(work / 350000) * 1.15, lowColumns = Math.max(1, Math.floor(columns / factor)), lowRows = Math.max(1, Math.floor(rows / factor));
    const low = rasterizeSculpture(mesh, { ...grid, columns: lowColumns, rows: lowRows, cellWidth: width / lowColumns, cellHeight: height / lowRows }, yaw, pitch, zoom);
    for (let y = 0; y < rows; y++) for (let x = 0; x < columns; x++) {
      const at = Math.min(lowRows - 1, Math.floor(y / rows * lowRows)) * lowColumns + Math.min(lowColumns - 1, Math.floor(x / columns * lowColumns)), i = y * columns + x;
      coverage[i] = low.coverage[at]; light[i] = low.light[at]; depth[i] = low.depth[at];
    }
    return { grid, coverage, depth, light, sampling: Math.max(columns / lowColumns, rows / lowRows) * low.sampling };
  }
  for (let i = 0; i < mesh.triangles.length; i += 3) {
    const a = mesh.triangles[i] * 4, b = mesh.triangles[i + 1] * 4, c = mesh.triangles[i + 2] * 4;
    const ax = projected[a], ay = projected[a + 1], bx = projected[b], by = projected[b + 1], cxp = projected[c], cyp = projected[c + 1];
    const denominator = (by - cyp) * (ax - cxp) + (cxp - bx) * (ay - cyp);
    if (Math.abs(denominator) < 1e-7) continue;
    const left = Math.max(0, Math.floor(Math.min(ax, bx, cxp))), right = Math.min(columns - 1, Math.ceil(Math.max(ax, bx, cxp)));
    const top = Math.max(0, Math.floor(Math.min(ay, by, cyp))), bottom = Math.min(rows - 1, Math.ceil(Math.max(ay, by, cyp)));
    for (let y = top; y <= bottom; y++) for (let x = left; x <= right; x++) {
      const wa = ((by - cyp) * (x + .5 - cxp) + (cxp - bx) * (y + .5 - cyp)) / denominator, wb = ((cyp - ay) * (x + .5 - cxp) + (ax - cxp) * (y + .5 - cyp)) / denominator, wc = 1 - wa - wb;
      if (wa < -.001 || wb < -.001 || wc < -.001) continue;
      const z = wa * projected[a + 2] + wb * projected[b + 2] + wc * projected[c + 2], index = y * columns + x;
      if (z <= depth[index]) continue;
      depth[index] = z; coverage[index] = 1; light[index] = wa * projected[a + 3] + wb * projected[b + 3] + wc * projected[c + 3];
    }
  }
  return { grid, coverage, depth, light, sampling: 1 };
}

export type DitherPattern = "ordered" | "halftone" | "diffusion" | "stipple";
export type InkTreatment = "hatch" | "crosshatch" | "contour";
export type PrintOptions = { kind: "dither" | "ink"; pattern?: DitherPattern; treatment?: InkTreatment; markSize?: number; density?: number; angle?: number; relief?: number };
const bayer = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5];
const noise = (x: number, y: number) => { const n = Math.sin(x * 127.1 + y * 311.7) * 43758.5453; return n - Math.floor(n); };
const fract = (value: number) => value - Math.floor(value);
export function sculpturePrint(frame: SculptureFrame, options: PrintOptions): Uint8Array {
  const { grid, coverage, light, depth } = frame, { columns, rows, cellWidth, cellHeight } = grid, marks = new Uint8Array(coverage.length);
  const density = sculptureNumber(options.density, 1, .5, 1.6), spacing = sculptureNumber(options.markSize, 8, 4, 16), angle = sculptureNumber(options.angle, -25, -180, 180) * Math.PI / 180, relief = sculptureNumber(options.relief, .55, 0, 1);
  const errors = options.pattern === "diffusion" ? new Float32Array(coverage.length) : undefined;
  for (let y = 0; y < rows; y++) for (let x = 0; x < columns; x++) {
    const i = y * columns + x;
    if (!coverage[i]) continue;
    const shade = Math.max(.06, Math.min(.98, (.18 + (1 - light[i]) * .85) * density));
    if (options.kind === "dither") {
      if (errors) {
        const value = shade + errors[i], hit = value >= .5 ? 1 : 0, error = value - hit;
        marks[i] = hit * 255;
        if (x + 1 < columns) errors[i + 1] += error * 7 / 16;
        if (y + 1 < rows) { if (x) errors[i + columns - 1] += error * 3 / 16; errors[i + columns] += error * 5 / 16; if (x + 1 < columns) errors[i + columns + 1] += error / 16; }
      } else {
        const threshold = options.pattern === "stipple" ? noise(x, y) : options.pattern === "halftone" ? Math.hypot(fract(x / 5) - .5, fract(y / 5) - .5) * 1.42 : (bayer[(y % 4) * 4 + x % 4] + .5) / 16;
        marks[i] = shade > threshold ? 255 : 0;
      }
    } else {
      const px = (x + .5) * cellWidth, py = (y + .5) * cellHeight, u = px * Math.cos(angle) + py * Math.sin(angle), v = -px * Math.sin(angle) + py * Math.cos(angle);
      const bend = depth[i] * spacing * 2.2 * relief, wobble = Math.sin(u / 37) * .1 * spacing;
      const line = Math.abs(fract((v + bend + wobble) / spacing) - .5), cross = Math.abs(fract((u - bend * .7) / (spacing * 1.2)) - .5);
      const contour = Math.abs(fract(depth[i] * (96 / spacing)) - .5);
      const edge = x === 0 || y === 0 || x === columns - 1 || y === rows - 1 || !coverage[i - 1] || !coverage[i + 1] || !coverage[i - columns] || !coverage[i + columns];
      const broken = shade > .5 || noise(Math.floor(u / 12), Math.floor((v + bend) / spacing)) < shade + .35;
      const hit = options.treatment === "contour" ? contour < .055 + shade * .08 || edge : (line < .05 + shade * .33 && broken) || (options.treatment === "crosshatch" && shade > .42 && cross < (shade - .38) * .32);
      marks[i] = hit && noise(x, y) > .035 ? 255 : 0;
    }
  }
  return marks;
}

export type GlyphSet = "density" | "digits" | "letters";
export const SCULPTURE_GLYPHS = { density: " .,:;=+*#%@", digits: " .1273456890", letters: " .iltrcoEXMW" } as const;
/** Edge cells use a local shape gradient, independently of the interior density ramp. */
export function sculptureCharacters(frame: SculptureFrame, set: GlyphSet = "density", edgeMatching = true): string[] {
  const { coverage, light, grid: { columns, rows } } = frame, ramp = SCULPTURE_GLYPHS[set], out = new Array<string>(coverage.length).fill(" ");
  for (let y = 0; y < rows; y++) for (let x = 0; x < columns; x++) {
    const i = y * columns + x;
    if (!coverage[i]) continue;
    out[i] = ramp[Math.max(1, Math.min(ramp.length - 1, Math.round(light[i] * (ramp.length - 2)) + 1))];
    if (!edgeMatching || set !== "density") continue;
    const sample = (dx: number, dy: number) => x + dx >= 0 && x + dx < columns && y + dy >= 0 && y + dy < rows ? coverage[i + dy * columns + dx] : 0;
    const gx = sample(1, -1) + 2 * sample(1, 0) + sample(1, 1) - sample(-1, -1) - 2 * sample(-1, 0) - sample(-1, 1);
    const gy = sample(-1, 1) + 2 * sample(0, 1) + sample(1, 1) - sample(-1, -1) - 2 * sample(0, -1) - sample(1, -1);
    if (Math.abs(gx) + Math.abs(gy) >= 3) out[i] = Math.abs(gx) > Math.abs(gy) * 1.7 ? "|" : Math.abs(gy) > Math.abs(gx) * 1.7 ? "_" : gx * gy > 0 ? "/" : "\\";
  }
  return out;
}

/** Compact opaque-cell path for a real, geometry-derived server/no-canvas fallback. */
export function sculpturePrintPath(marks: Uint8Array, columns: number) {
  let path = "";
  for (let i = 0; i < marks.length;) {
    if (!marks[i]) { i++; continue; }
    const x = i % columns, y = Math.floor(i / columns); let length = 1;
    while (x + length < columns && marks[i + length]) length++;
    path += `M${x} ${y}h${length}v1h-${length}z`; i += length;
  }
  return path;
}

/** Original, bounded geometry contract shared by the three print treatments. */
export type SculptureGeometryInput = {
  positions: ArrayLike<number>;
  triangles?: ArrayLike<number>;
  normals?: ArrayLike<number>;
};
export type SculptureGeometry = { positions: Float32Array; triangles: Uint16Array; normals: Float32Array };
export const SCULPTURE_LIMITS = { vertices: 16000, triangles: 20000, fileBytes: 8 * 1024 * 1024, imagePixels: 4000000, svgBytes: 128000 } as const;

export function sculptureGeometry(input: SculptureGeometryInput): SculptureGeometry {
  const length = input?.positions?.length ?? 0;
  if (!Number.isInteger(length) || length < 9 || length % 3 || length > SCULPTURE_LIMITS.vertices * 3) throw new Error("Use 3–16,000 vertices, with three coordinates per vertex.");
  const positions = Float32Array.from(input.positions);
  if (!positions.every(Number.isFinite)) throw new Error("The geometry contains a non-finite coordinate.");
  const count = length / 3, source = input.triangles ?? Array.from({ length: count }, (_, index) => index);
  if (!source.length || source.length % 3 || source.length > SCULPTURE_LIMITS.triangles * 3) throw new Error("Use a triangle mesh with at most 20,000 triangles.");
  const triangles = new Uint16Array(source.length);
  for (let i = 0; i < source.length; i++) {
    const value = source[i];
    if (!Number.isInteger(value) || value < 0 || value >= count) throw new Error("A triangle refers to a missing vertex.");
    triangles[i] = value;
  }
  const min = [Infinity, Infinity, Infinity], max = [-Infinity, -Infinity, -Infinity];
  for (let i = 0; i < length; i++) { const axis = i % 3; min[axis] = Math.min(min[axis], positions[i]); max[axis] = Math.max(max[axis], positions[i]); }
  const center = min.map((value, i) => (value + max[i]) / 2);
  let radius = 0;
  for (let i = 0; i < length; i += 3) radius = Math.max(radius, Math.hypot(positions[i] - center[0], positions[i + 1] - center[1], positions[i + 2] - center[2]));
  if (!Number.isFinite(radius) || radius < 1e-9) throw new Error("The geometry has no visible extent.");
  for (let i = 0; i < length; i++) positions[i] = (positions[i] - center[i % 3]) / radius;
  const normals = new Float32Array(length);
  if (input.normals) {
    if (input.normals.length !== length) throw new Error("Provide one normal for every vertex.");
    normals.set(Array.from(input.normals));
    if (!normals.every(Number.isFinite)) throw new Error("The geometry contains a non-finite normal.");
  } else {
    for (let i = 0; i < triangles.length; i += 3) {
      const a = triangles[i] * 3, b = triangles[i + 1] * 3, c = triangles[i + 2] * 3;
      const ux = positions[b] - positions[a], uy = positions[b + 1] - positions[a + 1], uz = positions[b + 2] - positions[a + 2];
      const vx = positions[c] - positions[a], vy = positions[c + 1] - positions[a + 1], vz = positions[c + 2] - positions[a + 2];
      const nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx;
      for (const target of [a, b, c]) { normals[target] += nx; normals[target + 1] += ny; normals[target + 2] += nz; }
    }
  }
  for (let i = 0; i < length; i += 3) {
    const size = Math.hypot(normals[i], normals[i + 1], normals[i + 2]);
    if (size < 1e-8) normals[i + 2] = 1;
    else { normals[i] /= size; normals[i + 1] /= size; normals[i + 2] /= size; }
  }
  return { positions, triangles, normals };
}

/** A sampled luminance relief with transparent cells removed. No image is uploaded. */
export function sculptureFromPixels(image: { width: number; height: number; data: ArrayLike<number> }, relief = .22): SculptureGeometry {
  const { width, height, data } = image;
  if (!Number.isInteger(width) || !Number.isInteger(height) || width < 2 || height < 2 || width * height > SCULPTURE_LIMITS.imagePixels || data.length !== width * height * 4) throw new Error("Use an RGBA image from 2×2 up to 4 million pixels.");
  const columns = Math.min(72, width), rows = Math.min(72, height), positions: number[] = [], alpha: boolean[] = [], triangles: number[] = [];
  const aspect = width / height, depth = Number.isFinite(relief) ? Math.max(0, Math.min(.6, relief)) : .22;
  for (let y = 0; y < rows; y++) for (let x = 0; x < columns; x++) {
    const px = Math.round(x / (columns - 1) * (width - 1)), py = Math.round(y / (rows - 1) * (height - 1)), at = (py * width + px) * 4;
    const light = (data[at] * .2126 + data[at + 1] * .7152 + data[at + 2] * .0722) / 255;
    positions.push((x / (columns - 1) * 2 - 1) * Math.min(aspect, 1), (1 - y / (rows - 1) * 2) / Math.max(aspect, 1), (light - .5) * depth);
    alpha.push(data[at + 3] >= 128);
  }
  for (let y = 0; y < rows - 1; y++) for (let x = 0; x < columns - 1; x++) {
    const a = y * columns + x, b = a + 1, c = a + columns, d = c + 1;
    if (alpha[a] && alpha[b] && alpha[c]) triangles.push(a, c, b);
    if (alpha[b] && alpha[c] && alpha[d]) triangles.push(b, c, d);
  }
  if (!triangles.length) throw new Error("The image is transparent or too small to form a surface. Choose an opaque image or a larger silhouette.");
  return sculptureGeometry({ positions, triangles });
}

